<script setup lang="ts">
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {idempotencyKey} from '@shared/net/http-client';import {managementGo} from '@/shared/management';
const {t}=useI18n();const m=ref(''),b=ref(''),name=ref('');const revision=ref(0);const busy=ref(false),failed=ref(false);let key=idempotencyKey();
onLoad(async q=>{m.value=q?.m||'';b.value=q?.b||'';if(b.value)try{const brand=await api.mBrand(b.value);name.value=brand.name;revision.value=brand.revision}catch{failed.value=true}});
async function save(){if(busy.value||!name.value.trim())return;busy.value=true;failed.value=false;try{const result=b.value?await api.mEditBrand(b.value,{name:name.value.trim(),expectedRevision:revision.value},key):await api.mCreateBrand({managementNo:m.value,name:name.value.trim(),status:'ACTIVE'},key);key=idempotencyKey();managementGo('brand_detail',{b:result.brandNo,m:m.value})}catch{failed.value=true}finally{busy.value=false}}
</script>
<template><sh-scaffold :failed="failed" title-key="management.brandInfo"><view class="sh-card"><view class="field"><text class="field__label">{{t('management.brandName')}}</text><input v-model="name" class="field__input" maxlength="100"/></view></view><view v-if="failed" class="sh-card">{{t('management.retry')}}</view><sh-actionbar><view class="sh-btn" :class="{'sh-btn--muted':busy||!name.trim()}" @tap="save">{{t(busy?'management.loading':'management.save')}}</view></sh-actionbar></sh-scaffold></template>
